    {
      "@id": "activity:translation-story_text_1-2026-07-08T02:17:51.926879+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T02:17:51.926879+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_1",
      "@type": "prov:Entity",
      "prov:value": "Aristotle walked as he taught. He believed the act of moving — through space, through questions, through observation — was itself a form of thinking. Two thousand years later, the research agrees."
    },
    {
      "@id": "entity:target-story_text_1-v1",
      "@type": "prov:Entity",
      "prov:value": "Aristóteles caminaba mientras enseñaba. Creía que el acto de moverse -a través del espacio, a través de preguntas, a través de la observación- era en sí mismo una forma de pensar. Dos mil años después, la investigación está de acuerdo.",
      "generated_by": {
        "@id": "activity:translation-story_text_1-2026-07-08T02:17:51.926879+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_1"
      }
    },
    {
      "@id": "activity:translation-story_text_2-2026-07-08T02:17:51.926879+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T02:17:51.926879+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_2",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware puts that insight in your pocket. Teachers design activities that bring curriculum to life in the real world. Students explore, capture, and reflect. Peri guides the inquiry. And learning — finally — moves."
    },
    {
      "@id": "entity:target-story_text_2-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware te lleva esa comprensión al bolsillo. Los profesores diseñan actividades que traen la currícula a vida en el mundo real. Los estudiantes exploran, capturan y reflexionan. Peri guía la investigación. Y finalmente, el aprendizaje se mueve.",
      "generated_by": {
        "@id": "activity:translation-story_text_2-2026-07-08T02:17:51.926879+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_2"
      }
    },
