    },
    {
      "@id": "activity:translation-meet_peri.step.2.desc-2026-07-08T02:36:59.561954+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T02:36:59.561954+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.2.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child records what they see, hear, or measure. Peri prompts for specifics if the answer is vague."
    },
    {
      "@id": "entity:target-meet_peri.step.2.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Tu hijo registra lo que ve, oye o mide. Peri pide detalles si la respuesta es vaga.",
