    {
      "@id": "entity:source-homeschool_section_desc",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware treats homeschool parents as both teacher and parent in one account. You own your children\\'s accounts directly — no link codes, no bureaucracy."
    },
    {
      "@id": "entity:target-homeschool_section_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware considera a los padres de la educación en el hogar como tanto maestro como padre en una sola cuenta. Usted es dueño directamente de las cuentas de sus hijos - sin códigos de enlace ni burocracia.",
      "generated_by": {
        "@id": "activity:translation-homeschool_section_desc-2026-07-08T02:43:44.616241+00:00"
      },
