    {
      "@id": "activity:translation-field_journal_desc-2026-07-08T03:16:44.337766+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T03:16:44.337766+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-field_journal_desc",
      "@type": "prov:Entity",
      "prov:value": "Students don't just do an activity — they record it. The Field Journal is where raw observations become structured knowledge. Back at their desk, students expand their notes with extended analysis, personal reflection, and connections to what they already know. Teachers can review, respond, and promote entries to the student's permanent portfolio."
    },
    {
      "@id": "entity:target-field_journal_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Los estudiantes no sólo realizan una actividad — la registran. El Cuaderno de Campo es donde las observaciones crudas se convierten en conocimiento estructurado. De vuelta en su escritorio, los estudiantes amplían sus notas con análisis extendido, reflexión personal y conexiones con lo que ya saben. Los maestros pueden revisar, responder y promover entradas al portfolio permanente del estudiante.",
      "generated_by": {
        "@id": "activity:translation-field_journal_desc-2026-07-08T03:16:44.337766+00:00"
      },
      "used_source": {
        "@id": "entity:source-field_journal_desc"
      }
    },
