    {
      "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T03:24:14.531136+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T03:24:14.531136+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr",
      "@type": "prov:Entity",
      "prov:value": "When you upload a PDF or CSV, Ollama extracts the criteria once and caches them. Re-uploading the same file skips Ollama entirely (checksum match). A different file triggers re-extraction. Pre-seeded state sets were hand-authored and are always instant. Sets expire annually — you'll see a warning near the expiry date."
    },
    {
      "@id": "entity:target-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-v1",
      "@type": "prov:Entity",
      "prov:value": "Al subir un PDF o CSV, Ollama extrae los criterios una vez y los almacena en caché. Volver a subir el mismo archivo omite a Ollama por completo (coincidencia de suma de verificación). Un archivo diferente desencadena la reextracción. Los conjuntos de estados preinstalados fueron escritos a mano y siempre son instantáneos. Los conjuntos caducan anualmente — verás una advertencia cerca de la fecha de caducidad.",
      "generated_by": {
        "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-08T03:24:14.531136+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr"
      }
    },
