    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware comenzó como un documento blanco escrito dentro de McGraw-Hill Education. Argumentaba que los dispositivos móviles con GPS transformarían el aprendizaje — que los estudiantes caminando por lugares reales, guiados por una investigación estructurada, podrían aprender de una manera que los libros de texto nunca permitieron.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-08T03:24:37.297800+00:00"
      },
      "used_source": {
