      "@id": "activity:translation-components_teacher_enhancedactivitybuilder.placeholder_eg_look_around_you_notice_the_layers_of_-2026-07-08T03:26:07.092298+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T03:26:07.092298+00:00",
