    },
    {
      "@id": "entity:source-components_teacher_enhancedactivitybuilder.placeholder_eg_look_around_you_notice_the_layers_of_",
      "@type": "prov:Entity",
      "prov:value": "e.g. Look around you. Notice the layers of the forest \\u2014 the tall canopy trees, the shrubs and ferns below, and the ground covered in moss and fallen logs. Find a spot to stand quietly for 60 seconds and observe \\u2014 what do you see, hear, and smell?"
    },
    {
      "@id": "entity:target-components_teacher_enhancedactivitybuilder.placeholder_eg_look_around_you_notice_the_layers_of_-v1",
      "@type": "prov:Entity",
      "prov:value": "Por ejemplo, mira a tu alrededor. Observa las capas del bosque: los árboles de la copa alta, los arbustos y helechos por debajo, y el suelo cubierto de musgo y troncos caídos. Encuentra un lugar para estar quieto durante 60 segundos y observar: ¿qué ves, oyes y hueles?",
      "generated_by": {
        "@id": "activity:translation-components_teacher_enhancedactivitybuilder.placeholder_eg_look_around_you_notice_the_layers_of_-2026-07-08T03:26:07.092298+00:00"
      },
      "used_source": {
        "@id": "entity:source-components_teacher_enhancedactivitybuilder.placeholder_eg_look_around_you_notice_the_layers_of_"
      }
    },
    {
      "@id": "activity:translation-components_teacher_enhancedactivitybuilder.placeholder_eg_choose_one_investigation_question_and-2026-07-08T03:26:07.092298+00:00",
