    {
      "@id": "activity:translation-team_1_bio-2026-07-08T03:32:31.816283+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T03:32:31.816283+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul pasó una década como maestro, cuatro años trabajando para empresas de tecnología educativa y ha estado experimentando con cómo salir del aprendizaje de los libros y las aulas durante dos décadas. Peripateticware aprovecha los avances en modelos de lenguaje grandes y utiliza tecnologías móviles para permitir que los estudiantes aprendan del mundo con la guía de sus maestros dondequiera que elijan moverse.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-08T03:32:31.816283+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
